{"code":"def transform(grid):
    h,w=len(grid),len(grid[0])
    # dominant separator color is the most common value on full separator rows/cols; here infer 3
    vals={x for row in grid for x in row}
    # find rows/cols having strong uniform dominant line color
    line_rows=[]
    for i,r in enumerate(grid):
        if len(set(r))==1: line_rows.append(i)
    line_cols=[]
    for j in range(w):
        if len({grid[i][j] for i in range(h)})==1: line_cols.append(j)
    # line color: values occurring on these lines
    from collections import Counter
    c=Counter()
    for i in line_rows: c.update(grid[i])
    for j in line_cols: c.update(grid[i][j] for i in range(h))
    base=c.most_common(1)[0][0] if c else grid[0][0]
    pts=[]
    for i in line_rows:
        for j in range(w):
            if grid[i][j]!=base: pts.append((i,j))
    for j in line_cols:
        for i in range(h):
            if grid[i][j]!=base: pts.append((i,j))
    if not pts:return [r[:] for r in grid]
    rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
    a,b=min(rs),max(rs); c1,d=max(0,min(cs)),max(cs)
    return [row[c1:d+1] for row in grid[a:b+1]]"}

